        _validate_response_schema(swagger_validator, first, expected_success_status=expected_status)

        # Attempt to parse next page token. If not present or falsy, skip further pagination for this case.
        ctype = first.headers.get("Content-Type", "")
        if "json" not in ctype.lower():
            pytest.skip(f"[Pagination][Case {idx}] Non-JSON response, cannot paginate")

        try:
            body = first.json()
        except Exception:
            pytest.skip(f"[Pagination][Case {idx}] Body not JSON parseable, cannot paginate")

        next_token = body.get("next_page_token")
        if not next_token:
            pytest.skip(f"[Pagination][Case {idx}] No next_page_token present in response, skipping further pagination")

        # Use the returned token to request the next page:
